import {
  PlaneGeometry,
  Mesh,
  MeshPhysicalNodeMaterial,
  TextureNode,
  Group,
  FloatNode,
  uniform,
  positionGeometry,
  normalGeometry,
  texture,
  uv,
  add,
  mul,
  Fn,
  vec3,
  float
} from 'three/webgpu';
import gsap from 'gsap';
import { toThree } from 'three/tsl';

export default function createNode(config, ctx) {
  const { position, rotation, scale, atlas, cinematicPrimitives } = config;
  const { textureLoader } = ctx;

  // Load the color and depth textures (these are cached)
  const colorTexture = textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  const depthTexture = textureLoader.load('/prism-mock/home/nodes/parallax-stack.depth.png');

  // Create the tessellated plane (64x64 segments)
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // Build displacement node using the depth map
  const displacementNode = Fn(() => {
    const depth = texture(depthTexture, uv()).r;
    const displacement = mul(depth, float(0.1)); // subtle displacement
    return add(positionGeometry, mul(normalGeometry, displacement));
  })();

  // Material with machined-metal PBR properties
  const material = new MeshPhysicalNodeMaterial();
  material.colorNode = texture(colorTexture, uv());
  material.positionNode = displacementNode;

  // PBR metalness, roughness, clearcoat
  material.metalnessNode = float(0.55);
  material.roughnessNode = float(0.5);
  material.clearcoatNode = float(0.25);

  // Enable anisotropy for brushed metal look (if supported)
  material.anisotropyNode = float(0.3);

  // Create the mesh
  const plane = new Mesh(geometry, material);
  plane.castShadow = true;
  plane.receiveShadow = true;

  // Wrap in a group for positioning and event handling
  const group = new Group();
  group.add(plane);

  // Position, rotation, scale from config
  group.position.copy(position);
  group.rotation.set(rotation.x, rotation.y, rotation.z);
  group.scale.copy(scale);

  // Apply cinematic primitives (parallax-scroll and depth-rotate)
  const cleanupPrimitives = [];
  cinematicPrimitives.forEach(p => {
    const cleanupFn = ctx.primitives[p.name](plane, p.params);
    if (cleanupFn) cleanupPrimitives.push(cleanupFn);
  });

  // Weighted-settle entrance animation (GSAP)
  const enterTimeline = gsap.timeline();
  enterTimeline.fromTo(plane.scale, { x: 0.8, y: 0.8, z: 0.8 }, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
    overwrite: true
  });

  // Hover effect: rise-in (subtle Y offset)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(plane.position, {
    y: 0.15,
    duration: 0.4,
    ease: 'power3.out'
  });

  // Event handlers attached to group.userData.handlers
  group.userData.handlers = {
    onPointerEnter: () => {
      hoverTimeline.play();
    },
    onPointerLeave: () => {
      hoverTimeline.reverse();
    },
    onClick: () => {
      // Emit event for hub-pricing.select
      if (group.userData.handlers.onEvent) {
        group.userData.handlers.onEvent('hub-pricing.select', {});
      }
    }
  };

  // Data binding handler (for trpc.visits.book.slot -> confirmPanel)
  // This will be invoked by parent to update the element
  group.userData.handlers.onDataUpdate = (data) => {
    // For now, we do nothing; parent will use the data for its own panel
  };

  // Cleanup function
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    enterTimeline.kill();
    hoverTimeline.kill();

    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose textures (they are managed by the cache, but we can let them be)
    // If deep cleanup needed, we can call dispose on the texture nodes
    // but that's handled by the loader cache.

    // Call cleanup functions from primitives
    cleanupPrimitives.forEach(fn => fn());
  };

  return group;
}
